test('capabilities are derived from whichever supported artifacts are present',()=>{assert.deepEqual(capabilitySummary([{kind:'ortho'},{kind:'dsm'}]),{assetKinds:['dsm','ortho'],capabilities:['dsm','orthophoto']});assert.deepEqual(capabilitySummary([{kind:'glb'}]),{assetKinds:['glb'],capabilities:['3d_model']});assert.deepEqual(capabilitySummary([{kind:'pointCloud'}]),{assetKinds:['pointCloud'],capabilities:['point_cloud']});});

for(const scenario of[
  {name:'queues verified OBJ plus GLB LOD generation when imported tiles are absent',files:['assets/odm_texturing/odm_textured_model_geo.obj','assets/odm_texturing/odm_textured_model_geo.glb'],type:'mesh_tiles'},
  {name:'queues the standard WebODM georeferenced mesh plus EPT backup layout when tiles are absent',files:['assets/odm_texturing/odm_textured_model_geo.obj','assets/odm_texturing/odm_textured_model_geo.mtl','assets/odm_texturing/odm_textured_model_geo.glb','assets/odm_texturing/odm_textured_model_geo_0.png','assets/entwine_pointcloud/ept.json'],type:'mesh_tiles'},
  {name:'regenerates imported native tiles as required KTX2 before viewer activation',files:['assets/odm_texturing/odm_textured_model_geo.obj','assets/odm_texturing/odm_textured_model_geo.glb','assets/3d_tiles/model/tileset.json','assets/3d_tiles/model/root.b3dm'],type:'mesh_tiles'},
])test(scenario.name,async(t)=>{const c=fixture(t);c.config.meshDerivativesEnabled=true;const source=path.join(c.config.datasetImportMount,scenario.type);for(const relative of scenario.files){const target=path.join(source,...relative.split('/'));fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,'fixture');}const project=c.processing.createProject({displayName:'LOD import'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:scenario.type,projectId:project.id,taskDisplayName:'LOD import'},subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'lod-import-worker');const complete=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(complete.status,'awaiting_derivatives',complete.errorMessage);assert.equal(complete.result.attempt.status,'derivatives');const jobs=c.db.prepare('SELECT derivative_type,request_json FROM derivative_jobs WHERE attempt_id=?').all(complete.result.attempt.id);assert.equal(jobs.length,1);assert.equal(jobs[0].derivative_type,scenario.type);const request=JSON.parse(jobs[0].request_json);assert.equal(request.optional,false);if(scenario.type==='lod_audit'){assert.equal(request.tilesRootKey,'datasets');assert.equal(request.generateFromObjOnFailure,true);assert.equal(complete.result.model.activeVersion.assets.some((asset)=>asset.kind==='tiles'),false,'native tiles stay quarantined until their v2 audit succeeds');}});

test('ZIP task imports map incremental extraction progress into the staging quarter',async(t)=>{const c=fixture(t),archive=path.join(c.config.datasetImportMount,'progress.zip');fs.writeFileSync(archive,Buffer.from('','base64'));const project=c.processing.createProject({displayName:'ZIP progress'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:'progress.zip',projectId:project.id,taskDisplayName:'ZIP progress'},subject:'ops:one',sessionId:'session'}),heartbeat=c.processing.heartbeatDatasetOperation.bind(c.processing),updates=[];c.processing.heartbeatDatasetOperation=(id,owner,value,...rest)=>{updates.push(value);return heartbeat(id,owner,value,...rest);};await processOneDatasetOperation(c,'zip-progress-worker');assert.equal(c.processing.getDatasetOperation(operation.id,'ops:one').status,'succeeded');const retained=c.db.prepare('SELECT id,state,cleanup_jobs_inserted FROM retained_imports WHERE operation_id=?').get(operation.id),cleanup=c.db.prepare('SELECT cleanup_type,status FROM import_cleanup_jobs WHERE retained_import_id=? ORDER BY cleanup_type').all(retained.id);assert.equal(retained.state,'ready');assert.equal(retained.cleanup_jobs_inserted,1);assert.deepEqual(cleanup.map(row=>({...row})),[{cleanup_type:'source_zip',status:'pending'},{cleanup_type:'staging_tree',status:'pending'}]);assert.equal(fs.existsSync(archive),true,'source ZIP remains until verified readiness');assert.ok(updates.some((value)=>value>0&&value<0.25),'extraction reports before the archive is fully staged');assert.ok(updates.some((value)=>value===0.25),'staging reaches exactly one quarter before discovery');});

test('ZIP task imports are staged from creation before derivative activation',async(t)=>{const c=fixture(t),archive=path.join(c.config.datasetImportMount,'atomic.zip');c.config.meshDerivativesEnabled=true;fs.writeFileSync(archive,makeZip([{path:'odm_texturing/odm_textured_model_geo.obj',data:'mesh'},{path:'odm_texturing/odm_textured_model_geo.glb',data:'glb'},{path:'entwine_pointcloud/ept.json',data:'{}'},{path:'3d_tiles/model/tileset.json',data:'{}'}]));const project=c.processing.createProject({displayName:'Atomic ZIP'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:'atomic.zip',projectId:project.id,taskDisplayName:'Atomic ZIP'},subject:'ops:one',sessionId:'session'}),activate=c.processing.activateImportedDerivativesForOperation.bind(c.processing);let observed=null;c.processing.activateImportedDerivativesForOperation=(operationId,owner,attemptId,specs,result,retainedLeaseToken)=>{const attempt=c.processing.getAttempt(attemptId),task=c.processing.getTask(attempt.taskId),output=c.processing.getModelOutput(attempt.resultModelVersionId),version=c.db.prepare('SELECT status FROM model_versions WHERE id=?').get(attempt.resultModelVersionId),model=c.db.prepare('SELECT status,active_version_id FROM models WHERE id=?').get(attempt.resultModelId);observed={attempt:attempt.status,progress:attempt.progress,task:task.status,output:output.status,version:version.status,model:model.status,activeVersionId:model.active_version_id};return activate(operationId,owner,attemptId,specs,result,retainedLeaseToken);};await processOneDatasetOperation(c,'atomic-zip-worker');assert.deepEqual(observed,{attempt:'ingesting',progress:0.95,task:'processing',output:'staged',version:'importing',model:'importing',activeVersionId:null});assert.equal(c.processing.getDatasetOperation(operation.id,'ops:one').status,'awaiting_derivatives');});

test('the exported WebODM task-backup layout detects viewable subsets and preserves authoritative task metrics',async(t)=>{const c=fixture(t),root=path.join(c.config.datasetImportMount,'Johnson-Road-backup');for(const relative of['data/backup.json','data/console_output.txt','assets/log.json','assets/cameras.json','assets/images.json','assets/task_output.txt','assets/odm_dem/dsm.tif','assets/odm_dem/dtm.tif','assets/odm_orthophoto/odm_orthophoto.tif','assets/odm_texturing/odm_textured_model_geo.obj','assets/odm_texturing/odm_textured_model_geo.glb','assets/odm_georeferencing/odm_georeferenced_model.laz','assets/entwine_pointcloud/ept.json','assets/entwine_pointcloud/ept-data/0.bin','assets/odm_report/report.pdf','assets/odm_report/shots.geojson']){const target=path.join(root,...relative.split('/'));fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,'fixture');}fs.writeFileSync(path.join(root,'assets','entwine_pointcloud','ept.json'),VALID_EPT);fs.mkdirSync(path.join(root,'assets','entwine_pointcloud','ept-hierarchy'),{recursive:true});fs.writeFileSync(path.join(root,'assets','entwine_pointcloud','ept-hierarchy','0-0-0-0.json'),'{}');fs.mkdirSync(path.join(root,'assets','odm_report'),{recursive:true});fs.writeFileSync(path.join(root,'assets','odm_report','stats.json'),JSON.stringify({point_cloud_statistics:{dense:true,stats:{statistic:[{count:428498832}]}},odm_processing_statistics:{average_gsd:0.3048},processing_statistics:{area:115092.96}}));fs.writeFileSync(path.join(root,'assets','odm_georeferencing','proj.txt'),'+proj=utm +zone=16 +datum=WGS84 +units=m');fs.writeFileSync(path.join(root,'assets','odm_georeferencing','odm_georeferencing_model_geo.txt'),'WGS84 UTM 16N\n435932 4897211\n');fs.writeFileSync(path.join(root,'assets','odm_georeferencing','odm_georeferenced_model.summary.json'),JSON.stringify({summary:{bounds:{minx:435895.3,miny:4897159.221,minz:211.914,maxx:435976.627,maxy:4897266.836,maxz:258.005}}}));for(let i=0;i<3;i++)fs.writeFileSync(path.join(root,`DJI_${i}.JPG`),'photo');fs.writeFileSync(path.join(root,'assets','odm_report','shots.geojson'),JSON.stringify({type:'FeatureCollection',features:[{type:'Feature',properties:{filename:'DJI_0.JPG'},geometry:{type:'Point',coordinates:[-87,44,200]}},{type:'Feature',properties:{filename:'missing.JPG'},geometry:{type:'Point',coordinates:[-87,44,201]}}]}));const project=c.processing.createProject({displayName:'Johnson Road'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:'Johnson-Road-backup',projectId:project.id,taskDisplayName:'Johnson Road'},subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'webodm-layout-worker');const complete=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(complete.status,'awaiting_derivatives',complete.errorMessage);assert.deepEqual(complete.result.assetKinds,['dsm','dtm','ept','glb','obj','ortho','report','shots']);assert.deepEqual(complete.result.capabilities,['3d_model','camera_positions','dsm','dtm','orthophoto','point_cloud']);assert.equal(complete.result.model.activeVersion.assets.some((asset)=>asset.relativePath.endsWith('assets/entwine_pointcloud/ept.json')),true);assert.equal(complete.result.model.activeVersion.assets.find((asset)=>asset.kind==='report').contentType,'application/pdf');const photos=c.repository.listCameraPhotos(complete.result.model.activeVersion.id);assert.equal(photos.length,1);assert.equal(photos[0].filename,'DJI_0.JPG');assert.equal(photos[0].rootKey,'datasets');assert.equal(path.isAbsolute(photos[0].relativePath),false);assert.equal(photos[0].relativePath.endsWith('/DJI_0.JPG'),true);assert.equal(complete.result.model.activeVersion.pointCount,428498832);assert.equal(complete.result.model.activeVersion.georef.crs,'WGS 84 / UTM zone 16N');assert.deepEqual(complete.result.model.activeVersion.georef.rtc,{e:435932,n:4897211,z:0});assert.ok(Math.abs(complete.result.model.activeVersion.georef.bboxCenter.x-3.9635)<1e-9);assert.equal(complete.result.model.activeVersion.metadata.processingMetrics.surveyedAreaM2,115092.96);});

test('the same WebODM task content can be intentionally imported twice with independent identities',async(t)=>{const c=fixture(t),source=path.join(c.config.datasetImportMount,'task-42');fs.mkdirSync(source);fs.writeFileSync(path.join(source,'odm_orthophoto.tif'),'orthophoto-only');const project=c.processing.createProject({displayName:'Migration target'}),request={sourceRelativePath:'task-42',projectId:project.id,taskDisplayName:'Task 42'},operation=c.processing.createWebodmTaskImportOperation({request,subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'webodm-import-worker');const complete=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(complete.status,'succeeded',complete.errorMessage);assert.deepEqual(complete.result.assetKinds,['ortho']);assert.deepEqual(complete.result.capabilities,['orthophoto']);assert.equal(complete.result.requiredDerivatives,undefined);assert.equal(complete.result.task.status,'ready_for_review');assert.equal(fs.existsSync(path.join(c.config.datasetImportMount,'task-42','odm_orthophoto.tif')),true,'operator source remains untouched');assert.equal(fs.existsSync(path.join(c.config.datasetsMount,complete.result.import.datasetId,'odm_orthophoto.tif')),true);
  const duplicate=c.processing.createWebodmTaskImportOperation({request:{...request,taskDisplayName:'Duplicate'},subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'webodm-import-worker');const repeated=c.processing.getDatasetOperation(duplicate.id,'ops:one');assert.equal(repeated.status,'succeeded',repeated.errorMessage);assert.equal(repeated.result.import.id,duplicate.id);assert.equal(repeated.result.import.sourceFingerprint,complete.result.import.sourceFingerprint);for(const key of['task','attempt'])assert.notEqual(repeated.result[key].id,complete.result[key].id,key);assert.notEqual(repeated.result.import.datasetId,complete.result.import.datasetId);assert.notEqual(repeated.result.model.id,complete.result.model.id);assert.notEqual(repeated.result.model.activeVersion.id,complete.result.model.activeVersion.id);assert.equal(fs.existsSync(path.join(c.config.datasetsMount,repeated.result.import.datasetId,'odm_orthophoto.tif')),true);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM webodm_task_imports WHERE source_fingerprint=?').get(complete.result.import.sourceFingerprint).n,2);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM processing_tasks WHERE project_id=?').get(project.id).n,2);assert.equal(c.db.prepare("SELECT COUNT(*) n FROM models WHERE provider='webodm'").get().n,2);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM model_versions').get().n,2);
});

