test('retained copy rejects a nested directory swap after path validation',async t=>{const c=fixture(t),source=path.join(c.config.datasetImportMount,'nested-swap');fs.mkdirSync(path.join(source,'nested'),{recursive:true});fs.writeFileSync(path.join(source,'nested','model.glb'),'nested mesh');const project=c.processing.createProject({displayName:'Nested swap'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:'nested-swap',projectId:project.id,taskDisplayName:'Nested swap'},subject:'ops:one',sessionId:'session'}),record=c.processing.recordRetainedImportManifest.bind(c.processing),lstat=fs.lstatSync,staged=path.join(c.config.cacheMount,'webodm-task-imports',operation.id,'extracted','nested'),escaped=path.join(c.config.cacheMount,`escaped-${operation.id}`);let armed=false,swapped=false;c.processing.recordRetainedImportManifest=(...args)=>{const result=record(...args);armed=true;return result;};fs.lstatSync=(candidate,...rest)=>{const result=lstat(candidate,...rest);if(armed&&!swapped&&(String(candidate).replaceAll('\\','/').endsWith('/nested')||String(candidate).replaceAll('\\','/').endsWith('/nested/model.glb'))){fs.renameSync(staged,escaped);fs.symlinkSync(escaped,staged,'dir');swapped=true;}return result;};try{await processOneDatasetOperation(c,'nested-swap-worker');}finally{fs.lstatSync=lstat;c.processing.recordRetainedImportManifest=record;}assert.equal(swapped,true);const failed=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(failed.status,'failed');assert.ok(['source_changed','retained_dependency_unsafe'].includes(failed.errorCode),failed.errorCode);assert.equal(c.processing.getDataset(JSON.parse(c.db.prepare('SELECT payload_json FROM dataset_operations WHERE id=?').get(operation.id).payload_json).ids.datasetId,true),null);});
