test('WebODM adopted bytes have one physical accounting owner',async t=>{const c=fixture(t),source=path.join(c.config.datasetImportMount,'accounting'),body=Buffer.from('one-physical-tree');fs.mkdirSync(source);fs.writeFileSync(path.join(source,'model.glb'),body);const project=c.processing.createProject({displayName:'Accounting'}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:'accounting',projectId:project.id,taskDisplayName:'Accounting'},subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'accounting-worker');const complete=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(complete.status,'succeeded',complete.errorMessage);const storage=c.processing.projectStorage(project.id);assert.equal(storage.project.datasetBytes,0);assert.equal(storage.project.outputBytes,body.length);assert.equal(storage.project.totalBytes,body.length);const overviewBytes=c.db.prepare("SELECT (SELECT COALESCE(SUM(d.byte_size),0) FROM datasets d WHERE d.status<>'trashed' AND d.storage_mode<>'external_reference' AND NOT EXISTS (SELECT 1 FROM processing_attempts a JOIN model_outputs o ON o.attempt_id=a.id WHERE a.dataset_id=d.id AND o.status<>'trashed' AND o.storage_mode='adopted'))+(SELECT COALESCE(SUM(byte_size),0) FROM model_outputs WHERE status<>'trashed' AND storage_mode<>'external_reference') AS bytes").get();assert.equal(Number(overviewBytes.bytes),body.length);});

test('a duplicate import survives final-commit lease loss and retries with its own stable identities',async t=>{const c=fixture(t),source=path.join(c.config.datasetImportMount,'lease-loss');fs.mkdirSync(source);fs.writeFileSync(path.join(source,'model.glb'),'lease-loss');const project=c.processing.createProject({displayName:'Lease loss'}),request={sourceRelativePath:'lease-loss',projectId:project.id,taskDisplayName:'Lease loss'},first=c.processing.createWebodmTaskImportOperation({request,subject:'ops:one',sessionId:'session'});await processOneDatasetOperation(c,'first-worker');const original=c.processing.getDatasetOperation(first.id,'ops:one');assert.equal(original.status,'succeeded',original.errorMessage);const operation=c.processing.createWebodmTaskImportOperation({request:{...request,taskDisplayName:'Lease loss duplicate'},subject:'ops:one',sessionId:'session'}),payload=JSON.parse(c.db.prepare('SELECT payload_json FROM dataset_operations WHERE id=?').get(operation.id).payload_json),complete=c.processing.completeDatasetOperation.bind(c.processing);let lost=true;c.processing.completeDatasetOperation=(...args)=>lost?(lost=false,false):complete(...args);await processOneDatasetOperation(c,'lost-worker');c.processing.completeDatasetOperation=complete;assert.equal(c.processing.getDatasetOperation(operation.id,'ops:one').status,'failed');assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(`processing-ready-${payload.ids.attemptId}`).n,0);assert.equal(c.processing.getDataset(payload.ids.datasetId,true),null);assert.equal(fs.existsSync(path.join(c.config.datasetsMount,payload.ids.datasetId)),false);assert.equal(c.processing.retryDatasetOperation(operation.id,'ops:one').status,'queued');await processOneDatasetOperation(c,'recovery-worker');const recovered=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(recovered.status,'succeeded',recovered.errorMessage);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(`processing-ready-${payload.ids.attemptId}`).n,1);assert.equal(recovered.result.task.id,payload.ids.taskId);assert.equal(recovered.result.import.datasetId,payload.ids.datasetId);assert.equal(recovered.result.model.id,payload.ids.modelId);assert.equal(recovered.result.model.activeVersion.id,payload.ids.versionId);assert.notEqual(recovered.result.task.id,original.result.task.id);assert.notEqual(recovered.result.import.datasetId,original.result.import.datasetId);assert.notEqual(recovered.result.model.id,original.result.model.id);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM webodm_task_imports WHERE source_fingerprint=?').get(original.result.import.sourceFingerprint).n,2);});

for(const stage of['adoption','finalize','task','model','output'])test(`task import rolls back and retries stable identities after ${stage} failure`,async(t)=>{const c=fixture(t),source=path.join(c.config.datasetImportMount,`fault-${stage}`);fs.mkdirSync(source);fs.writeFileSync(path.join(source,'model.glb'),`model-${stage}`);const project=c.processing.createProject({displayName:`Fault ${stage}`}),operation=c.processing.createWebodmTaskImportOperation({request:{sourceRelativePath:`fault-${stage}`,projectId:project.id,taskDisplayName:`Fault ${stage}`},subject:'ops:one',sessionId:'session'}),payload=JSON.parse(c.db.prepare('SELECT payload_json FROM dataset_operations WHERE id=?').get(operation.id).payload_json),restore=[];const inject=(target,name)=>{const original=target[name].bind(target),fault=()=>{throw Object.assign(new Error(`fault after ${stage}`),{code:'fault_injected'});};target[name]=(...args)=>{const result=original(...args);return result&&typeof result.then==='function'?result.then(fault):fault();};restore.push(()=>{target[name]=original;});};if(stage==='adoption')inject(c.storage,'adoptImport');else if(stage==='finalize')inject(c.processing,'finalizeDataset');else if(stage==='task')inject(c.processing,'createTask');else if(stage==='model')inject(c.repository,'upsertModelVersion');else inject(c.processing,'registerModelOutput');await processOneDatasetOperation(c,`fault-${stage}-worker`);for(const fn of restore)fn();const failed=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(failed.status,'failed');assert.equal(failed.errorCode,'fault_injected');assert.equal(c.processing.getDataset(payload.ids.datasetId,true),null);assert.equal(c.processing.getTask(payload.ids.taskId),null);assert.equal(c.processing.getAttempt(payload.ids.attemptId),null);assert.equal(c.repository.getModelVersion(payload.ids.modelId,payload.ids.versionId),null);assert.equal(fs.existsSync(path.join(c.config.datasetsMount,payload.ids.datasetId)),false);assert.equal(fs.existsSync(source),true,'operator source remains authoritative');assert.equal(c.processing.retryDatasetOperation(operation.id,'ops:one').status,'queued');await processOneDatasetOperation(c,`retry-${stage}-worker`);const recovered=c.processing.getDatasetOperation(operation.id,'ops:one');assert.equal(recovered.status,'succeeded',recovered.errorMessage);assert.equal(recovered.result.task.id,payload.ids.taskId);assert.equal(recovered.result.attempt.id,payload.ids.attemptId);assert.equal(recovered.result.model.id,payload.ids.modelId);assert.equal(recovered.result.model.activeVersion.id,payload.ids.versionId);assert.equal(c.processing.pendingCatalogAdoptionRecoveries().some((item)=>item.id===operation.id),false);});
